import type { GrammarTopic } from '../types';
import topicsJson from '../../content/grammar/topics.json';

// Grammar explainers ship as local JSON (generated by content/authoring/grammar.py). Admins can
// rework them or add new ones in the grammar studio (grammar_topic rows, src/lib/grammarStudio.ts):
// a published version replaces the shipped topic in place (same object, so screens that hold it
// update), and new sections join the list.
const topics: GrammarTopic[] = topicsJson as GrammarTopic[];
const bySlug = new Map(topics.map((t) => [t.slug, t]));
const shipped = new Map<string, GrammarTopic>(topics.map((t) => [t.slug, structuredClone(t)]));

export function getGrammarTopics(): GrammarTopic[] {
  return topics;
}

export function getGrammarTopic(slug: string): GrammarTopic | undefined {
  return bySlug.get(slug);
}

/** Is this one of the sections that ship with the app (content/grammar/topics.json)? */
export function isShippedGrammar(slug: string): boolean {
  return shipped.has(slug);
}

/** The section as it ships, before any live edits. */
export function shippedGrammar(slug: string): GrammarTopic | undefined {
  const t = shipped.get(slug);
  return t ? structuredClone(t) : undefined;
}

/** Puts a published version live: replaces the topic's content in place, or adds a new section. */
export function setLiveGrammar(topic: GrammarTopic): void {
  const fresh = structuredClone(topic);
  const cur = bySlug.get(topic.slug);
  if (cur) {
    for (const k of Object.keys(cur)) delete (cur as unknown as Record<string, unknown>)[k];
    Object.assign(cur, fresh);
    return;
  }
  topics.push(fresh);
  topics.sort((a, b) => a.level - b.level);
  bySlug.set(fresh.slug, fresh);
}

/** Takes a section off the air: a shipped one goes back to its shipped wording, a new one disappears. */
export function unsetLiveGrammar(slug: string): void {
  const orig = shipped.get(slug);
  if (orig) return setLiveGrammar(orig);
  const i = topics.findIndex((t) => t.slug === slug);
  if (i !== -1) topics.splice(i, 1);
  bySlug.delete(slug);
}
